import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/domain/services/derived-governance.ts","src/domain/services/derived-graph.ts","src/domain/services/derived-governance.test.ts","src/domain/services/derived-graph.test.ts","src/infrastructure/database/event-log.ts","tests/infrastructure/database/extraction-batch-replay.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/operation-admission.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/infrastructure/database/event-log.ts","kind":"change-ordinary-last-candidate-semantics","from":": ordinary.get(candidate.edgeId)!;","to":": await graphRepo.save(candidate);","pattern":"ordinary repeated graph"},{"path":"src/domain/services/derived-governance.ts","kind":"omit-scope-conflict","from":"throw new Error(\"Derived governance identity or scope conflict\");","to":"","pattern":"scope mismatch"},{"path":"src/domain/services/derived-governance.ts","kind":"replace-prior-control","from":"...previous.toParams()","to":"...incoming.toParams()","pattern":"preserves .* control"},{"path":"src/domain/services/derived-governance.ts","kind":"lose-governance-provenance","from":"...previous.sourceEventIds, ","to":"","pattern":"control and provenance"},{"path":"src/domain/services/derived-governance.ts","kind":"permit-disjoint-grants","from":"consentStatus = \"denied\";","to":"consentStatus = \"granted\";","pattern":"disjoint grants"},{"path":"src/domain/services/derived-governance.ts","kind":"weaken-consent","from":"? previous.consentStatus : incoming.consentStatus","to":"? incoming.consentStatus : incoming.consentStatus","pattern":"derived consent combines"},{"path":"src/domain/services/derived-governance.ts","kind":"broaden-grant-scopes","from":"previous.consentScopes.filter(scope => incoming.consentScopes.includes(scope))","to":"[...new Set([...previous.consentScopes,...incoming.consentScopes])]","pattern":"derived consent combines"},{"path":"src/domain/services/derived-governance.ts","kind":"extend-governance-expiry","from":"? previous.expiresAt : incoming.expiresAt","to":"? incoming.expiresAt : incoming.expiresAt","pattern":"derived expiry"},{"path":"src/domain/services/derived-governance.ts","kind":"lose-quarantine","from":"? previous.redactionState : incoming.redactionState","to":"? incoming.redactionState : incoming.redactionState","pattern":"preserves .* control"},{"path":"src/domain/services/derived-graph.ts","kind":"allow-graph-identity-collision","from":"throw new Error(\"Derived graph identity conflict\");","to":"","pattern":"refuses identity conflict"},{"path":"src/domain/services/derived-graph.ts","kind":"lose-graph-provenance","from":"...(previous?.sourceEventIds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"lose-graph-source-kind","from":"...(previous?.sourceKinds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"extend-graph-validity","from":"? previous.validTo : incoming.validTo","to":"? incoming.validTo : incoming.validTo","pattern":"keeps overlap"},{"path":"src/domain/services/derived-graph.ts","kind":"resurrect-graph-validity","from":"? previous.validFrom : incoming.validFrom","to":"? incoming.validFrom : incoming.validFrom","pattern":"later bound"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-policy-merge","from":"if (!existingGovernance || context.batchTargets.has(`persona:${saved.entryId}`))","to":"if (!existingGovernance)","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-policy-merge","from":"if (!existingGovernance || protectedIdentity)","to":"if (!existingGovernance)","pattern":"retains denied batch consent"},{"path":"src/infrastructure/database/event-log.ts","kind":"ignore-ordinary-contributor-policy","from":"if (!context.batchTargets.has(`${entry.surface}:${entry.targetId}`)) return entry;","to":"if (!context.batchEffects.has(event.eventId)) return entry;","pattern":"revoked ordinary"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-target-discovery","from":"if (persona) batchTargets.add(`persona:${persona.entryId}`);","to":"","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-target-discovery","from":"for (const edge of graphEdgesFromFact(fact, effect.observedAt)) batchTargets.add(`graph:${edge.edgeId}`);","to":"","pattern":"shared derived graph"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local=match[1].startsWith('src/')?match[1]:'src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-shared-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-shared-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-shared-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

