urceEventIds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"lose-graph-source-kind","from":"...(previous?.sourceKinds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"extend-graph-validity","from":"? previous.validTo : incoming.validTo","to":"? incoming.validTo : incoming.validTo","pattern":"keeps overlap"},{"path":"src/domain/services/derived-graph.ts","kind":"resurrect-graph-validity","from":"? previous.validFrom : incoming.validFrom","to":"? incoming.validFrom : incoming.validFrom","pattern":"later bound"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-policy-merge","from":"if (!existingGovernance || context.batchTargets.has(`persona:${saved.entryId}`))","to":"if (!existingGovernance)","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-policy-merge","from":"if (!existingGovernance || protectedIdentity)","to":"if (!existingGovernance)","pattern":"retains denied batch consent"},{"path":"src/infrastructure/database/event-log.ts","kind":"ignore-ordinary-contributor-policy","from":"if (!context.batchTargets.has(`${entry.surface}:${entry.targetId}`)) return entry;","to":"if (!context.batchEffects.has(event.eventId)) return entry;","pattern":"revoked ordinary"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-target-discovery","from":"if (persona) batchTargets.add(`persona:${persona.entryId}`);","to":"","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-target-discovery","from":"for (const edge of graphEdgesFromFact(fact, effect.observedAt)) batchTargets.add(`graph:${edge.edgeId}`);","to":"","pattern":"shared derived graph"}];

