const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/domain/services/derived-governance.ts","src/domain/services/derived-graph.ts","src/domain/services/derived-governance.test.ts","src/domain/services/derived-graph.test.ts","src/infrastructure/database/event-log.ts","tests/infrastructure/database/extraction-batch-replay.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/operation-admission.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/domain/services/derived-governance.ts","kind":"omit-scope-conflict","from":"throw new Error(\"Derived governance identity or scope conflict\");","to":"","pattern":"scope mismatch"},{"path":"src/domain/services/derived-governance.ts","kind":"replace-prior-control","from":"...previous.toParams()","to":"...incoming.toParams()","pattern":"preserves .* control"},{"path":"src/domain/services/derived-governance.ts","kind":"lose-governance-provenance","from":"...previous.sourceEventIds, ","to":"","pattern":"control and provenance"},{"path":"src/domain/services/derived-governance.ts","kind":"permit-disjoint-grants","from":"consentStatus = \"denied\";","to":"consentStatus = \"granted\";","pattern":"disjoint grants"},{"path":"src/domain/services/derived-governance.ts","kind":"weaken-consent","from":"? previous.consentStatus : incoming.consentStatus","to":"? incoming.consentStatus : incoming.consentStatus","pattern":"derived consent combines"},{"path":"src/domain/services/derived-governance.ts","kind":"broaden-grant-scopes","from":"previous.consentScopes.filter(scope => incoming.consentScopes.includes(scope))","to":"[...new Set([...previous.consentScopes,...incoming.consentScopes])]","pattern":"derived consent combines"},{"path":"src/domain/services/derived-governance.ts","kind":"extend-governance-expiry","from":"? previous.expiresAt : incoming.expiresAt","to":"? incoming.expiresAt : incoming.expiresAt","pattern":"derived expiry"},{"path":"src/domain/services/derived-governance.ts","kind":"lose-quarantine","from":"? previous.redactionState : incoming.redactionState","to":"? incoming.redactionState : incoming.redactionState","pattern":"preserves .* control"},{"path":"src/domain/services/derived-graph.ts","kind":"allow-graph-identity-collision","from":"throw new Error(\"Derived graph identity conflict\");","to":"","pattern":"refuses identity conflict"},{"path":"src/domain/services/derived-graph.ts","kind":"lose-graph-provenance","from":"...(previous?.sourceEventIds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"lose-graph-source-kind","from":"...(previous?.sourceKinds ?? []), ","to":"","pattern":"annotations evolve"},{"path":"src/domain/services/derived-graph.ts","kind":"extend-graph-validity","from":"? previous.validTo : incoming.validTo","to":"? incoming.validTo : incoming.validTo","pattern":"keeps overlap"},{"path":"src/domain/services/derived-graph.ts","kind":"resurrect-graph-validity","from":"? previous.validFrom : incoming.validFrom","to":"? incoming.validFrom : incoming.validFrom","pattern":"later bound"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-policy-merge","from":"if (!existingGovernance || context.batchTargets.has(`persona:${saved.entryId}`))","to":"if (!existingGovernance)","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-policy-merge","from":"if (!existingGovernance || protectedIdentity)","to":"if (!existingGovernance)","pattern":"retains denied batch consent"},{"path":"src/infrastructure/database/event-log.ts","kind":"ignore-ordinary-contributor-policy","from":"if (!context.batchTargets.has(`${entry.surface}:${entry.targetId}`)) return entry;","to":"if (!context.batchEffects.has(event.eventId)) return entry;","pattern":"revoked ordinary"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-persona-target-discovery","from":"if (persona) batchTargets.add(`persona:${persona.entryId}`);","to":"","pattern":"prior persona suppression"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-graph-target-discovery","from":"for (const edge of graphEdgesFromFact(fact, effect.observedAt)) batchTargets.add(`graph:${edge.edgeId}`);","to":"","pattern":"shared derived graph"}];

