for(const id of['Q100.4.2.2.2.2','Q100.4.2.2.2','Q100.4.2.2','Q100.4.2'])get(id).progress={...get(id).progress,status:'Shared derived behavior verified; unsupported-consumer boundary and final reader acceptance open',next:next.progress.next,sharedGovernanceEvidence:evidence};
get('Q100.4.2.2.2.2').observed_gap='The earlier shared graph denied-consent RED is repaired with scoped evidence. Tagged v4.0.3 still clears projections and ignores batches. Consumer activation/rollback, complete reader quality/adversarial review, audit/pipeline and native interrupted-chain proof remain. No writer activation.';
get('Q100.4.2.2.2.2.3').observed_gap+=' Include truncated persona identity collision behavior and consumer-boundary proof in final reader review. Existing purposeful consent-scope enforcement is a broader privacy obligation, not proven by this merge helper.';
get('Q100.4.2.13').observed_gap+=' Shared-derived repair adds a prepass over batch graph/persona targets and indexed lookup/merge for protected graph identities; retained compatibility timings are not a scaling qualification.';
const catalog=discoverInventory(process.cwd()),manifest=read(root+'quality-classifications.json');assert.equal(catalog.files.length,508);
for(const m of measure.measurement.files){const file=catalog.files.find(f=>f.path===m.path);assert(file);let row=manifest.files.find((r:any)=>r.path===m.path);if(!row){row={path:m.path,package:'package.json',tier:'S',rationale:'Derived record governance, provenance and identity integrity with adversarial tests.',applicability:{mode:'measure',reason:'Executable integrity behavior/test; no exclusion approved.'},decisionStatus:'proposed - independent review pending'};manifest.files.push(row);}row.sourceHash=file.sourceHash;row.inspection={sourceRevision:'af40c20 + current source hash',anchor:item.id,scope:'Shared-derived scoped behavior; final reader/quality and consumer activation remain'};row.metricApplicability={status:'Scoped diagnostic; complete changed-line/platform/final review pending',sourceHash:file.sourceHash,evidence,metrics:Object.fromEntries(['statements','branches','functions','lines'].map(name=>[name,{observedCounterTotal:m.metrics[name].total,observedPercent:m.metrics[name].pct,proposal:'measure - completeness unverified'}]))};}
