const free=statfsSync(process.cwd());save(evidence,{item_id:item.id,status:'verified - scoped shared derived behavior only',recordedAt:new Date().toISOString(),startingRevision:'af40c2046adf310786e51da7b704ff55c6ea8e28',cwd:process.cwd(),verification:item.verification,outcome:item.progress,counts,current,native,diagnosticCoverage:measure,decisionChecks:faults,reds:['red','order-red','identity-red','controls-final-red','expiry-red','ordinary-behavior-red'].map(name=>({exit:1,path:stem+name+'.txt',output:text(stem+name+'.txt')})),corrections:{initialCurrent:read(stem+'initial-compat.json'),initialPinned:read(stem+'initial-native.json'),initialDiagnostic:read(stem+'initial-measure.json'),initialFaults:read(stem+'initial-faults.json'),reasons:['Both initial broad collectors hit300000ms and returned null exit with partial output under four heavy concurrent jobs. Not passing evidence. Repeated final collectors with fewer competing jobs and600000ms bounded collector cap; individual15000ms test timeout unchanged.','Initial provenance fault survived because the second fixture repeated the first source ID. Corrected to disjoint source IDs and repeated all faults.','Review found ordinary duplicate candidates changed first-governance annotation when saveMany became sequential. Retained behavioral RED; preserve legacy last-candidate semantics for unrelated graph identities and add targeted fault.','Two prior-control fixture attempts failed before assertions (private helper import, then unsupported suppress operation). Corrected to public Fact API and update operation; retained meaningful final persona consent RED and green.','.git test path initially required explicit ./ prefix; subsequent command executed intended failure.']},checks:[{command:'bun run typecheck',exit:0,output:text(stem+'types.txt')},{command:'Strict changed/new-test compilation',exit:0,config:read(stem+'tests-tsconfig.json'),output:text(stem+'test-types.txt')},{command:'bun run test:isolation',exit:0,output:text(stem+'isolation.txt')}],limits:[item.observed_gap,next.progress.next,'Narrow event-log metrics remain below policy. No full-suite/package/changed-line/Linux/hosted/install/desktop/final-review claim. Domain helpers have30and26instrumented branches; tests have nonzero denominators.','Old consumer RED and original kill-before-audit replacement-chain defect remain. Domain helpers do not authorize purpose-specific data egress or repair old installed binaries.','No canonical source, provider/model, hook, replication, installation or workspace authority changed. Owned synthetic fixtures only; previously rejected cleanup, shared-temp admission authority and Git temp object remain preserved. Three inboxes and R03/P03/A03 remain. Embedding experiment follows baseline acceptance.'],disk:{freeBytes:free.bavail*free.bsize},validation:{catalogFiles:508,packages:catalog.packages.length,ledgerItems:277,acyclic:true,currentItem:ledger.current_item,source:text(stem+'checkpoint.ts')}});
